const s = wb.getWorksheet('ورقة1');
const rows = s.getRange('A2:E8').getValues();
const last = new Map();
for (const r of rows) {
  const b = r[1];
  const cur = last.get(b);
  if (!cur || r[0] > cur[0]) last.set(b, [...r]);
  else if (r[0] === cur[0]) cur[4] += r[4];
}
const out = [...last.values()];
log(JSON.stringify(rows), JSON.stringify(out));
const h2fmt = s.getRange('H2').getStyle().getNumberFormat?.();
log('H2 fmt', h2fmt);
s.getRange('H2:L4').setValues(out);
s.getRange('H2:H4').getStyle().setNumberFormat(h2fmt ?? 'm/d/yyyy');
wb.getRange("'ورقة1'!H1:L5")

