const s = wb.getWorksheet('ورقة1');
const out=[];
for (const r of [2,3,4]) {
  const b = s.getRange('I'+r).getValues()[0][0];
  const d = await wb.evaluate(`=MAXIFS('ورقة1'!A2:A8,'ورقة1'!B2:B8,"${b}")`);
  const q = await wb.evaluate(`=SUMIFS('ورقة1'!E2:E8,'ورقة1'!B2:B8,"${b}",'ورقة1'!A2:A8,${d})`);
  out.push([b,d,q,s.getRange('H'+r).getCell().getText?.(),s.getRange('H'+r).getValues()[0][0],s.getRange('L'+r).getValues()[0][0]]);
}
JSON.stringify(out)

